import sys

def parse_beats(text):
    beats_map = {'o': 4, 'o|': 2, '.|': 1}
    i = 0
    total = 0
    n = len(text)
    while i < n:
        # skip whitespace
        if text[i].isspace():
            i += 1
            continue
        # try longest match first
        if i + 2 <= n and text[i:i+2] == 'o|':
            total += beats_map['o|']
            i += 2
        elif i + 2 <= n and text[i:i+2] == '.|':
            total += beats_map['.|')
            i += 2
        elif text[i] == 'o':
            total += beats_map['o']
            i += 1
        else:
            # skip unrelated character
            i += 1
    return total

def main():
    data = sys.stdin.read()
    total_beats = parse_beats(data)
    print(total_beats)

