def is_valid_filename(filename: str) -> bool:
    # Exactly one dot that splits name and extension
    if filename.count('.') != 1:
        return False
    name, ext = filename.split('.', 1)

    # Non-empty name before the dot
    if not name:
        return False

    # Name starts with an alphabetic character
    if not name[0].isalpha():
        return False

    # At most 3 digits total in the entire filename
    digits = sum(ch.isdigit() for ch in filename)
    if digits > 3:
        return False

    # Extension in allowed set
    if ext not in {'txt', 'exe', 'dll'}:
        return False

    return True

