def filter_words_by_consonants(s: str, n: int) -> list[str]:
    """
    Selects words from string s where the count of consonants equals n.
    Splits s by spaces, filters empty strings, counts consonants per word,
    and appends matches to result. Returns list of words.
    """
    def is_consonant(char: str) -> bool:
        return char.isalpha() and char.lower() not in 'aeiou'

    def count_consonants(word: str) -> int:
